int main(int argc,char**argv){@autoreleasepool{
 if(argc!=4)return 2;NSString*srcdir=@(argv[1]),*out=@(argv[2]);[[NSFileManager defaultManager]createDirectoryAtPath:out withIntermediateDirectories:YES attributes:nil error:NULL];NSError*error=nil;id<MTLDevice>d=MTLCreateSystemDefaultDevice();NSString*source=[NSString stringWithContentsOfFile:[srcdir stringByAppendingPathComponent:@"contrast-probe.metal"]encoding:NSUTF8StringEncoding error:&error];MTLCompileOptions*o=[MTLCompileOptions new];o.fastMathEnabled=YES;id<MTLLibrary>lib=[d newLibraryWithSource:source options:o error:&error];if(!lib){fprintf(stderr,"%s\n",error.description.UTF8String);return 3;}
 NSUInteger n=66048;NSMutableData*input=[NSMutableData dataWithLength:n*4*4];float*p=input.mutableBytes;NSData*first=[NSData dataWithContentsOfFile:[srcdir stringByAppendingPathComponent:@"contrast-first512.f32"]];if(first.length!=512*4*4)return 4;memcpy(p,first.bytes,first.length);uint32_t seed=20261018;for(NSUInteger i=512;i<n;i++){for(int c=0;c<3;c++){seed=1664525u*seed+1013904223u;p[i*4+c]=(seed>>8)*(1.f/16777216.f);}p[i*4+3]=.1f;}
 id<MTLBuffer>in=[d newBufferWithBytes:p length:input.length options:MTLResourceStorageModeShared],debug=[d newBufferWithLength:n*23*4*4 options:MTLResourceStorageModeShared],output=[d newBufferWithLength:n*4*2 options:MTLResourceStorageModeShared],dots=[d newBufferWithLength:n*4*2 options:MTLResourceStorageModeShared];id<MTLCommandQueue>q=[d newCommandQueue];
