 [input writeToFile:[out stringByAppendingPathComponent:@"input.f32"]atomically:YES];[[NSData dataWithBytes:debug.contents length:debug.length]writeToFile:[out stringByAppendingPathComponent:@"checkpoints.f32"]atomically:YES];[[NSData dataWithBytes:output.contents length:output.length]writeToFile:[out stringByAppendingPathComponent:@"output.f16"]atomically:YES];[[NSData dataWithBytes:dots.contents length:dots.length]writeToFile:[out stringByAppendingPathComponent:@"dot-mix.f16"]atomically:YES];NSDictionary*m=@{@"pixels":@(n),@"input_shape":@[@(n),@4],@"checks_shape":@[@(n),@23,@4],@"device":d.name,@"os":NSProcessInfo.processInfo.operatingSystemVersionString};[[NSJSONSerialization dataWithJSONObject:m options:NSJSONWritingPrettyPrinted error:NULL]writeToFile:[out stringByAppendingPathComponent:@"metadata.json"]atomically:YES];return 0;
